#!/usr/bin/env bash
# test-antigravity-adapter.sh — the Antigravity CLI adapter (platforms/antigravity/).
#
# WHAT THIS PINS
#   platforms/antigravity/plugin.json and mcp_config.json are generated by
#   scripts/build-antigravity-plugin.sh from .claude-plugin/plugin.json and the
#   `antigravity` overlay in platforms/manifests.source.json. Antigravity's
#   plugin.json schema is CLOSED ({name, description}, additionalProperties
#   false), so the one thing that would break an install silently is a field
#   leaking in from the canonical manifest; and the one thing this adapter must
#   NOT ship is a hooks.json nobody has seen fire. Both are asserted here, plus
#   drift and the §21 adapter contract.
#
# Runs without an `agy` binary (none is available; the CLI is not open source).
# Needs jq and python3. Exit 0 if all pass, 1 otherwise.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
# shellcheck source=tests/lib/harness.sh
source "$ROOT/tests/lib/harness.sh"

harness_require jq python3
GEN="$ROOT/scripts/build-antigravity-plugin.sh"
DIR="$ROOT/platforms/antigravity"
[ -f "$GEN" ] || { echo "FATAL: generator not found at $GEN"; exit 1; }

TMP="$(harness_tmpdir)"

assert_exit() {
  local name="$1" want="$2"; shift 2
  local out got
  out=$("$@" 2>&1); got=$?
  if [ "$got" -eq "$want" ]; then ok "$name"; else bad "$name" "expected exit $want, got $got: ${out:0:300}"; fi
}
make_copy() {
  local dst="$1"
  mkdir -p "$dst/.claude-plugin" "$dst/platforms/antigravity" "$dst/scripts"
  cp "$ROOT/.claude-plugin/plugin.json" "$dst/.claude-plugin/plugin.json"
  cp "$ROOT/platforms/manifests.source.json" "$dst/platforms/manifests.source.json"
  cp "$ROOT/scripts/github-mcp.sh" "$dst/scripts/github-mcp.sh"
  cp "$DIR/plugin.json" "$DIR/mcp_config.json" "$dst/platforms/antigravity/"
}
edit_json() { local f="$1" q="$2"; jq "$q" "$f" > "$f.tmp" && mv "$f.tmp" "$f"; }

section "generator"
assert_exit "build-antigravity-plugin.sh --check passes on the tree" 0 bash "$GEN" "$ROOT" --check
assert_exit "--help exits 0" 0 bash "$GEN" --help
assert_exit "an unknown flag is rejected" 1 bash "$GEN" "$ROOT" --bogus

C="$TMP/drift"; make_copy "$C"
edit_json "$C/platforms/antigravity/plugin.json" '.description = "hand edit"'
assert_exit "a hand-edited plugin.json fails --check" 1 bash "$GEN" "$C" --check
C="$TMP/drift-src"; make_copy "$C"
edit_json "$C/platforms/manifests.source.json" '.antigravity.plugin_description = "new text"'
assert_exit "an edited overlay without a regenerate fails --check" 1 bash "$GEN" "$C" --check
assert_exit "a normal run after the edit succeeds" 0 bash "$GEN" "$C"
judge "...and the output carries the new description" "new text" "$(jq -r .description "$C/platforms/antigravity/plugin.json")"
C="$TMP/bad-name"; make_copy "$C"
edit_json "$C/.claude-plugin/plugin.json" '.name = "tamirs.superpowers"'
assert_exit "a name outside ^[a-zA-Z0-9-_]+$ is exit 2" 2 bash "$GEN" "$C"
C="$TMP/bad-ph"; make_copy "$C"
edit_json "$C/platforms/manifests.source.json" '.antigravity.mcpServers.github.args = ["${extensionPath}/scripts/github-mcp.sh"]'
assert_exit "a placeholder in an MCP arg is exit 2 (Antigravity documents none)" 2 bash "$GEN" "$C"
C="$TMP/bad-field"; make_copy "$C"
edit_json "$C/platforms/manifests.source.json" '.antigravity.mcpServers.github.url = "https://x"'
assert_exit "an undocumented MCP field is exit 2" 2 bash "$GEN" "$C"
C="$TMP/bad-script"; make_copy "$C"
rm -f "$C/scripts/github-mcp.sh"
assert_exit "an MCP arg naming a missing script is exit 2" 2 bash "$GEN" "$C"

section "plugin.json: the closed schema"
P="$DIR/plugin.json"
judge "plugin.json parses" 0 "$(jq empty "$P" >/dev/null 2>&1; echo $?)"
judge "exactly the keys name and description" "description name" "$(jq -r 'keys | sort | join(" ")' "$P")"
judge "name is the canonical plugin name" "$(jq -r .name "$ROOT/.claude-plugin/plugin.json")" "$(jq -r .name "$P")"
judge "name matches ^[a-zA-Z0-9-_]+$" yes "$(if jq -r .name "$P" | grep -qE '^[a-zA-Z0-9_-]+$'; then echo yes; else echo no; fi)"
judge "description is non-empty" yes "$(if [ -n "$(jq -r '.description // ""' "$P")" ]; then echo yes; else echo no; fi)"
judge "no version/author/keywords leaked in (closed schema)" 0 "$(jq '[.version, .author, .keywords, .["$schema"]] | map(select(. != null)) | length' "$P")"

section "mcp_config.json: the documented stdio shape"
M="$DIR/mcp_config.json"
judge "mcp_config.json parses" 0 "$(jq empty "$M" >/dev/null 2>&1; echo $?)"
judge "the only top-level key is mcpServers" "mcpServers" "$(jq -r 'keys | join(" ")' "$M")"
judge "a github server is declared" yes "$(if jq -e '.mcpServers.github' "$M" >/dev/null; then echo yes; else echo no; fi)"
judge "it is a stdio server (command), not a legacy url/httpUrl" "yes" \
  "$(if jq -e '.mcpServers.github | has("command") and (has("url")|not) and (has("httpUrl")|not)' "$M" >/dev/null; then echo yes; else echo no; fi)"
judge "only documented stdio fields" "" "$(jq -r '.mcpServers[] | keys[] | select(IN("command","args","env","cwd") | not)' "$M")"
missing=""
while IFS= read -r a; do
  case "$a" in *.sh) [ -f "$ROOT/$a" ] || missing="$missing $a" ;; esac
done < <(jq -r '.mcpServers[].args[]?' "$M")
judge "every script in args exists in the tree" "" "$missing"
judge "no placeholder (Antigravity documents none)" 0 "$(grep -c '\${' "$M")"
judge "no credential-shaped literal" "" "$(grep -oE '(ghp|gho|ghu|ghs|github_pat)_[A-Za-z0-9_]{20,}' "$M" || true)"

section "what must NOT ship"
judge "no hooks.json (firing on agy is unverified)" no "$(exists "$DIR/hooks.json")"

section "adapter contract (§21)"
Y="$DIR/adapter.yaml"
judge "adapter.yaml exists" yes "$(exists "$Y")"
if python3 -c 'import yaml' >/dev/null 2>&1; then
  judge "adapter.yaml parses as YAML" 0 "$(python3 -c 'import yaml,sys; yaml.safe_load(open(sys.argv[1]))' "$Y" >/dev/null 2>&1; echo $?)"
  readyaml() { python3 -c 'import yaml,sys; d=yaml.safe_load(open(sys.argv[1])); v=d
for k in sys.argv[2].split("."): v=v[k]
print(v)' "$Y" "$1" 2>/dev/null; }
else
  skip "adapter.yaml YAML parse" "PyYAML not installed"
  readyaml() { awk -v k="$1" '$1 == k":" {sub(/^[^:]*:[[:space:]]*/, ""); print; exit}' "$Y"; }
fi
judge "id matches the directory name" antigravity "$(readyaml id)"
judge "registry_key is antigravity_cli" antigravity_cli "$(readyaml registry_key)"
judge "the registry has an antigravity_cli surface" yes \
  "$(if jq -e '.platforms.gemini.surfaces.antigravity_cli' "$ROOT/core/capabilities/platforms.json" >/dev/null; then echo yes; else echo no; fi)"
judge "install.doc exists" yes "$(exists "$ROOT/docs/user/install/antigravity.md")"
judge "validation.command names this test" "bash tests/test-antigravity-adapter.sh" \
  "$(awk '/^validation:/{inv=1;next} inv && /^[^[:space:]]/{inv=0} inv && /^  command:/{sub(/^  command:[[:space:]]*/,"");print;exit}' "$Y")"
judge "README names the migration route" yes "$(has "$(cat "$DIR/README.md")" "agy plugin import gemini")"
judge "README says hooks.json is deliberately absent" yes "$(has "$(cat "$DIR/README.md")" "no \`hooks.json\`")"
judge "install doc names the migration route" yes "$(has "$(cat "$ROOT/docs/user/install/antigravity.md")" "agy plugin import gemini")"
judge "no model name anywhere in the adapter" "" "$(grep -liE 'sonnet|opus|haiku|gemini-[0-9]|flash' "$DIR"/* 2>/dev/null || true)"
judge "this test file is executable" yes "$(if [ -x "$ROOT/tests/test-antigravity-adapter.sh" ]; then echo yes; else echo no; fi)"

section "live CLI (agy) — nightly territory"
if harness_have agy; then
  rc=0; out="$(cd "$TMP" && portable_timeout 60 agy plugin list --json </dev/null 2>&1)" || rc=$?
  # A launcher shim on PATH with no real binary behind it (cmux ships one) exits
  # 127 with "agy not found in PATH": the CLI is absent, so skip as below. Only
  # that message counts — a 127 from a real agy (an internal command not found)
  # stays a failure.
  if [ "$rc" -eq 0 ]; then ok "agy plugin list --json runs"
  elif [ "$rc" -eq 127 ] && [[ "$out" == *"agy not found in PATH"* ]]; then skip "agy plugin install/list" "agy resolves to a shim that reports command-not-found (exit 127) — nightly job territory"
  else bad "agy plugin list --json" "${out:0:200}"; fi
else
  skip "agy plugin install/list" "agy not on PATH — nothing here is measured against a live binary"
fi

harness_summary
